<?php
require '/wordpress/wp-load.php';wp_set_current_user(1);require_once ABSPATH.'wp-admin/includes/plugin.php';
foreach(['woocommerce/woocommerce.php','elementor/elementor.php','redux-framework/redux-framework.php','foodu-core/foodu-core.php','woocommerce-gateway-dummy-master/woocommerce-gateway-dummy.php','nestora-store/nestora-store.php'] as $plugin){$r=activate_plugin($plugin);if(is_wp_error($r))throw new Exception($plugin.': '.$r->get_error_message());}
switch_theme('nestora');
if(!class_exists('WooCommerce')){echo 'Plugins activated; run seed.php again in the next request.';return;}
if(get_option('nestora_seed_complete')){echo 'Nestora content already seeded; preserving edits.';return;}
WC_Install::install();
update_option('blogname','Nestora');update_option('blogdescription','Make every corner feel like home.');update_option('timezone_string','Asia/Karachi');update_option('permalink_structure','/%postname%/');update_option('default_comment_status','closed');
foreach(get_posts(['post_type'=>['page','post'],'post_status'=>'publish','posts_per_page'=>-1]) as $p){if(in_array($p->post_name,['hello-world','sample-page','shop','cart','checkout','my-account']))wp_trash_post($p->ID);}
foreach(['woocommerce_currency'=>'USD','woocommerce_default_country'=>'PK:PB','woocommerce_store_city'=>'Sahiwal','woocommerce_store_postcode'=>'57000','woocommerce_calc_taxes'=>'no','woocommerce_manage_stock'=>'yes','woocommerce_notify_low_stock'=>'yes','woocommerce_notify_no_stock'=>'yes','woocommerce_stock_format'=>'','woocommerce_enable_reviews'=>'yes','woocommerce_enable_coupons'=>'yes','woocommerce_enable_guest_checkout'=>'yes','woocommerce_enable_checkout_login_reminder'=>'yes','woocommerce_enable_signup_and_login_from_checkout'=>'yes','woocommerce_enable_myaccount_registration'=>'yes','woocommerce_registration_generate_username'=>'yes','woocommerce_registration_generate_password'=>'no','woocommerce_ship_to_destination'=>'shipping','woocommerce_enable_shipping_calc'=>'yes','woocommerce_allowed_countries'=>'all','woocommerce_ship_to_countries'=>'','woocommerce_customer_default_location'=>'base','woocommerce_email_from_name'=>'Nestora','woocommerce_email_from_address'=>'nestora@example.invalid','woocommerce_email_base_color'=>'#3f4a3c','woocommerce_email_background_color'=>'#faf6f0','woocommerce_custom_orders_table_enabled'=>'no','woocommerce_task_list_hidden'=>'yes','woocommerce_onboarding_profile'=>['completed'=>true,'skipped'=>true]] as $key=>$value)update_option($key,$value);
$catalog=json_decode(file_get_contents(ABSPATH.'wp-content/uploads/nestora/catalog.json'),true);$pages=json_decode(file_get_contents(ABSPATH.'wp-content/uploads/nestora/pages.json'),true);
require_once ABSPATH.'wp-admin/includes/image.php';
function ns_media($relative,$title,$width=700,$height=700){$file=ABSPATH.'wp-content/uploads/nestora/'.$relative;$id=wp_insert_attachment(['post_title'=>$title,'post_mime_type'=>str_ends_with($relative,'.jpg')?'image/jpeg':'image/png','post_status'=>'inherit'],$file);update_post_meta($id,'_wp_attached_file','nestora/'.$relative);wp_update_attachment_metadata($id,['width'=>$width,'height'=>$height,'file'=>'nestora/'.$relative,'sizes'=>[],'image_meta'=>[]]);update_post_meta($id,'_wp_attachment_image_alt',$title);return $id;}
$logo=ns_media('logo.png','Nestora logo',520,150);$icon=ns_media('favicon.png','Nestora site icon',512,512);$hero=ns_media('living-room.jpg','Warm, calm living room',1600,1067);set_theme_mod('custom_logo',$logo);update_option('site_icon',$icon);update_option('woocommerce_email_header_image',wp_get_attachment_url($logo));
$cats=[];foreach($catalog['categories'] as $c){$term=wp_insert_term($c['name'],'product_cat',['slug'=>$c['slug'],'description'=>$c['description']]);if(is_wp_error($term)){$existing=get_term_by('slug',$c['slug'],'product_cat');$cats[$c['slug']]=$existing->term_id;}else $cats[$c['slug']]=$term['term_id'];}
$product_ids=[];foreach($catalog['products'] as $index=>$item){$product=new WC_Product_Simple();$product->set_name($item['name']);$product->set_slug($item['slug']);$product->set_status('publish');$product->set_catalog_visibility('visible');$product->set_description($item['description']);$product->set_short_description($item['short']);$product->set_sku($item['sku']);$product->set_regular_price((string)$item['price']);if($item['sale'])$product->set_sale_price((string)$item['sale']);$product->set_manage_stock(true);$product->set_stock_quantity($item['stock']);$product->set_stock_status('instock');$product->set_weight((string)$item['weight']);$product->set_category_ids([$cats[$item['category']]]);$product->set_featured($item['featured']);$product->set_menu_order($index);$product->set_reviews_allowed(true);$image=ns_media($item['image'],$item['name'].' — original product illustration');$product->set_image_id($image);$product->save();$product_ids[$item['slug']]=$product->get_id();if($index%10===0)update_term_meta($cats[$item['category']],'thumbnail_id',$image);}
$ids=[];foreach($pages as $page){$ids[$page['slug']]=wp_insert_post(['post_type'=>'page','post_status'=>'publish','post_title'=>$page['title'],'post_name'=>$page['slug'],'post_content'=>$page['content']]);}
update_option('show_on_front','page');update_option('page_on_front',$ids['home']);foreach(['shop'=>'shop','cart'=>'cart','checkout'=>'checkout','myaccount'=>'my-account','terms'=>'terms'] as $opt=>$slug)update_option('woocommerce_'.$opt.'_page_id',$ids[$slug]);update_option('wp_page_for_privacy_policy',$ids['privacy']);
$main=wp_create_nav_menu('Nestora / Main menu');foreach(['home'=>'Home','shop'=>'Shop','about'=>'Our story','contact'=>'Contact'] as $slug=>$label)wp_update_nav_menu_item($main,0,['menu-item-title'=>$label,'menu-item-object'=>'page','menu-item-object-id'=>$ids[$slug],'menu-item-type'=>'post_type','menu-item-status'=>'publish']);
$footer=wp_create_nav_menu('Nestora / Footer menu');foreach(['shipping-returns'=>'Shipping & returns','faq'=>'FAQs','privacy'=>'Privacy & credits','terms'=>'Terms','my-account'=>'My account'] as $slug=>$label)wp_update_nav_menu_item($footer,0,['menu-item-title'=>$label,'menu-item-object'=>'page','menu-item-object-id'=>$ids[$slug],'menu-item-type'=>'post_type','menu-item-status'=>'publish']);set_theme_mod('nav_menu_locations',['nestora-main'=>$main,'nestora-footer'=>$footer]);
$zone=new WC_Shipping_Zone();$zone->set_zone_name('Pakistan');$zone->set_zone_order(1);$zone->add_location('PK','country');$zone->save();foreach([['flat_rate','Standard Delivery (3–7 days)','4'],['flat_rate','Express Delivery (1–3 days)','9'],['free_shipping','Free standard shipping','0']] as [$method,$title,$cost]){$instance=$zone->add_shipping_method($method);update_option('woocommerce_'.$method.'_'.$instance.'_settings',$method==='free_shipping'?['title'=>$title,'requires'=>'min_amount','min_amount'=>'75','ignore_discounts'=>'no']:['title'=>$title,'tax_status'=>'none','cost'=>$cost]);}
$world=new WC_Shipping_Zone(0);$world_id=$world->add_shipping_method('flat_rate');update_option('woocommerce_flat_rate_'.$world_id.'_settings',['title'=>'International Shipping','tax_status'=>'none','cost'=>'18']);
update_option('woocommerce_cod_settings',['enabled'=>'yes','title'=>'Cash on Delivery','description'=>'Pay in cash when your order arrives. Demonstration orders are not fulfilled.','instructions'=>'Pay in cash when your order arrives.','enable_for_methods'=>[],'enable_for_virtual'=>'no']);
update_option('woocommerce_dummy_settings',['enabled'=>'yes','title'=>'Test payment — no real charge','description'=>'Official WooCommerce Dummy Payments gateway. This simulates a successful payment for coursework. Do not enter card details.','result'=>'success','hide_for_non_admin_users'=>'no']);
$coupon=new WC_Coupon();$coupon->set_code('WELCOME10');$coupon->set_discount_type('percent');$coupon->set_amount(10);$coupon->set_individual_use(true);$coupon->set_usage_limit_per_user(1);$coupon->set_description('Nestora Club: 10% off a first order.');$coupon->save();
update_option('nestora_page_ids',$ids);update_option('nestora_product_ids',$product_ids);update_option('nestora_log_email',true);update_option('nestora_seed_complete',true);flush_rewrite_rules();wc_delete_product_transients();echo wp_json_encode(['pages'=>$ids,'products'=>count($product_ids),'categories'=>count($cats),'mysql'=>$GLOBALS['wpdb']->db_version()]);
